import React, { useState } from 'react';
import { Link } from 'react-router-dom';

function EmotionRecommendPage({ movies = [] }) {
  const [selectedEmotion, setSelectedEmotion] = useState(null);
  const [recommendedMovie, setRecommendedMovie] = useState(null);
  const [loading, setLoading] = useState(false);

  // 선택형 감정 버튼 리스트
  const emotionOptions = [
    { id: 'comfort', label: '나는 오늘 위로가 필요해', keyword: '드라마' },
    { id: 'laugh', label: '나는 오늘 웃음이 필요해', keyword: '코미디' },
    { id: 'thrill', label: '나는 오늘 짜릿한 자극이 필요해', keyword: '액션' },
    { id: 'romance', label: '나는 오늘 설렘이 필요해', keyword: '로맨스' }
  ];

  const handleSelectEmotion = (option) => {
    setSelectedEmotion(option.label);
    setLoading(true);
    setRecommendedMovie(null);

    setTimeout(() => {
      let chosen = null;

      // 메인 화면 영화 목록(movies)이 존재할 경우 해당 목록에서 우선 탐색
      if (movies && movies.length > 0) {
        // 간단히 목록 내에서 랜덤 혹은 첫 번째 영화 매칭 (또는 전체 중 하나 선택)
        const randomIndex = Math.floor(Math.random() * movies.length);
        chosen = movies[randomIndex];
      }

      // 만약 메인 영화 데이터가 없거나 부족할 경우의 기본 백업 데이터
      if (!chosen) {
        chosen = {
          title: '메가박스 시그니처 추천작',
          overview: '오늘 당신의 기분에 완벽하게 어울리는 감동적인 상영작입니다.',
          backdrop_path: null,
          poster_path: null,
          openDt: '2026'
        };
      }

      setRecommendedMovie(chosen);
      setLoading(false);
    }, 500);
  };

  return (
    <div className="w-full min-h-screen bg-white py-16 px-6 text-zinc-900 flex flex-col items-center" style={{ fontFamily: 'Pretendard, sans-serif' }}>
      <div className="w-full max-w-3xl space-y-10">
        
        {/* 상단 타이틀 영역 */}
        <div className="text-center space-y-3">
          <span className="text-xs font-black tracking-widest text-[#503396] uppercase bg-purple-50 px-3 py-1 rounded-full border border-purple-100">
            MEGABOX EMOTION CARE
          </span>
          <h2 className="text-3xl md:text-4xl font-black text-zinc-900 tracking-tight">
            오늘의 감정에 맞는 영화를 골라드려요
          </h2>
          <p className="text-xs text-zinc-500 font-bold">
            마음이 끌리는 문구를 선택하시면, 현재 상영작 중 가장 잘 어울리는 영화를 추천해 드립니다.
          </p>
        </div>

        {/* 문체형 선택 버튼 그리드 */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {emotionOptions.map((option) => (
            <button
              key={option.id}
              onClick={() => handleSelectEmotion(option)}
              className={`p-5 rounded-2xl text-left font-black text-sm transition-all shadow-sm border ${
                selectedEmotion === option.label
                  ? 'bg-[#503396] text-white border-[#503396] shadow-md scale-[1.02]'
                  : 'bg-zinc-50 hover:bg-purple-50/50 text-zinc-800 border-zinc-200 hover:border-[#503396]/30'
              }`}
            >
              <div className="flex items-center justify-between">
                <span>{option.label}</span>
                <span className="text-lg">✨</span>
              </div>
            </button>
          ))}
        </div>

        {/* 로딩 상태 */}
        {loading && (
          <div className="text-center py-12 text-[#503396] font-bold animate-pulse text-sm">
            메인 상영작 중에서 마음에 쏙 드는 영화를 찾는 중입니다...
          </div>
        )}

        {/* 추천 결과 카드 (화이트 & 퍼플 톤) */}
        {recommendedMovie && !loading && (
          <div className="bg-white border border-zinc-200 rounded-3xl p-8 shadow-xl flex flex-col md:flex-row items-center gap-8 animate-fade-in">
            
            {/* 포스터 영역 */}
            <div className="w-44 h-60 rounded-2xl bg-zinc-100 overflow-hidden shadow-md shrink-0 border border-zinc-200 flex items-center justify-center">
              {recommendedMovie.poster_path || recommendedMovie.backdrop_path ? (
                <img 
                  src={`https://image.tmdb.org/t/p/w500${recommendedMovie.poster_path || recommendedMovie.backdrop_path}`} 
                  alt={recommendedMovie.title} 
                  className="w-full h-full object-cover" 
                />
              ) : (
                <span className="text-xs text-zinc-400 font-bold">MEGABOX MOVIE</span>
              )}
            </div>

            {/* 컨텐츠 및 설명 영역 */}
            <div className="flex flex-col justify-center space-y-4 text-left w-full">
              <div>
                <span className="text-[11px] font-black text-[#503396] bg-purple-50 px-3 py-1 rounded-full border border-purple-100">
                  {selectedEmotion}에 어울리는 추천작
                </span>
                <h3 className="text-2xl md:text-3xl font-black text-zinc-900 mt-3 mb-2">
                  {recommendedMovie.title}
                </h3>
                <p className="text-xs text-zinc-600 leading-relaxed font-medium line-clamp-3">
                  {recommendedMovie.overview || "일상에 특별한 감동과 여운을 선사할 메가박스 추천 상영작입니다."}
                </p>
              </div>

              {/* 하단 액션 버튼 */}
              <div className="flex gap-3 pt-2">
                <Link 
                  to="/schedule" 
                  className="flex-grow text-center py-3.5 bg-[#503396] hover:bg-[#3b2570] text-white font-black text-xs rounded-xl transition shadow-md"
                >
                  상영시간표 및 예매하기
                </Link>
                <button 
                  onClick={() => { setSelectedEmotion(null); setRecommendedMovie(null); }} 
                  className="px-5 py-3.5 bg-zinc-100 hover:bg-zinc-200 text-zinc-700 font-black text-xs rounded-xl transition"
                >
                  다시 고르기
                </button>
              </div>
            </div>

          </div>
        )}

      </div>
    </div>
  );
}

export default EmotionRecommendPage;
